package com.agacostays.payroll.repository; import com.agacostays.payroll.entity.Payroll; import com.agacostays.payroll.enums.PayrollStatus; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface PayrollRepository extends JpaRepository<Payroll,Long>{Optional<Payroll> findByStaffIdAndMonthAndYear(Long staffId,Integer month,Integer year); List<Payroll> findByBranchIdAndMonthAndYear(Long branchId,Integer month,Integer year); List<Payroll> findByStaffIdOrderByYearDescMonthDesc(Long staffId); Page<Payroll> findByBranchId(Long branchId,Pageable p); List<Payroll> findByMonthAndYear(Integer month,Integer year);}